def find_smallest_root_of_function(x1: float, x2: float) -> float:
    """ Given a positive and a negative floating point number find the
    smallest root of function f(x) = x**2 + 2 * x.

    >>> find_smallest_root_of_function(3.5, 4.5)
    6.0
    """
    # find the number where the f(x) = 0
    while (x2 - x1) >= 0:
        x_mid = (x2 + x1) / 2.0
        f_x_mid = x_mid**2 + 2 * x_mid
        if f_x_mid == 0:
            return x_mid
        if f_x_mid < 0:
            x1 = x_mid
        else:
            x2 = x_mid
    # if x2 - x1 is less than zero the function did not converge
    # so return the last value from x1 to x2
    return x2


