def get_max_depth(group: str) -> int:
    """ Given a single group, output the deepest level of nesting.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    """
    deepest_level = 0
    current_level = 0

    for char in group:
        if char == '(':
            current_level += 1
        elif char == ')':
            current_level -= 1
        deepest_level = max(deepest_level, current_level)
    return deepest_level + 1


