def truncate_number(number: str) -> str:
    """ Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1).

    Return the decimal part of the number as a string.
    >>> truncate_number(3.5)
    '0.5'
    """
    if not isinstance(number, str):
        raise ValueError("Number must be a string")
    elif number.count(".") != 1:
        raise ValueError("Number must have two characters")
    elif number[0] == ".":
        raise ValueError("Number must have a left part")
    elif number[-1] != ".":
        raise ValueError("Number must have a right part")
    else:
        return number[1:-1]

    return number - int(number)

