def _parse_nested_parens(paren_string: str) -> List[int]:
    paren_list = [char for char in paren_string]
    stack: List[int] = []
    stack_depth: int = 0
    output_list: List[int] = []
    for char in paren_list:
        if char == '(':
            stack.append(char)
            stack_depth += 1
            output_list.append(0)
        elif char == ')':
            stack.pop()
            stack_depth -= 1
            if output_list[-1] == 0:
                output_list.append(stack_depth)
            else:
                output_list[-1] = max(output_list[-1], stack_depth)
    return output_list


