def parse_nested_parens_recursion(paren_string: str) -> List[int]:
    """ Helper function for parse_nested_parens """
    if '(' not in paren_string:
        return [0]

    l = paren_string.index('(')
    r = paren_string.rindex(')')

    if r - l == 2:
        return [1]

    return [1 + max(parse_nested_parens_recursion(paren_string[:l - 1]), parse_nested_parens_recursion(paren_string[r + 1:])) for _ in
            range(2)]


