def remove_zeroes(number: float) -> str:
    """ Given a floating point number, if the number has only one digit
    after the decimal point then append zero to that.
    >>> remove_zeroes(10)
    '10.0'
    """
    number_str = str(number)
    if number_str.count('.') == 1 and number_str.count('0') == 1:
        return number_str + '0'
    return number_str

