def parse_group(paren_group: str) -> List[str]:
    """ Input to this function is a single string for a group of nested parentheses.
    E.g. (()()) will be split into three groups: ['(', ')', '(']
    Your function must have a parameter representing the entire group and must return the deepest level of nesting of parentheses.

    >>> parse_group('()')
    ['(', ')']
    >>> parse_group('(()())')
    ['(', ')', '(']
    """
    start = 0
    end = 0
    while start < len(paren_group):
        if start > 0 and paren_group[start - 1] == '(':
            start += 1
            continue
        end += 1
        if start + end == len(paren_group):
            break
        if paren_group[start + end] == ')':
            end += 1
        else:
            start += 1
    return list(paren_group[start:end + start])


