def reverse_iterative(numbers: List[int]) -> List[int]:
    """ Return a list with all elements of input list `numbers` in reverse order using `iterative` approach
    >>> reverse_iterative([1, 2, 3])
    [3, 2, 1]
    """
    result = []
    for i in range(len(numbers) - 1, -1, -1):
        result.append(numbers[i])
    return result


def reverse_recursive(numbers: List[int]) -> List[int]:
    """ Return a list with all elements of input list `numbers` in reverse order using `recursive` approach
    >>> reverse_recursive([1, 2, 3])
    [3, 2, 1]
    """
    if len(numbers) == 0:
        return []
    return [numbers[-1]] + reverse_recursive(numbers[:-1])


